-- ─────────────────────────────────────────────────────────────────────────
-- ROC / MCA rules and checklists (docs/roc-mca-filing-spec.md, track A).
-- GENERATED by scripts/gen-calendar-v2-rules.ts from calendar-v2-rules.ts and
-- roc-checklists.ts — edit those and re-run the script; do not edit by hand.
--
--   * Rule fixes on databases that already ran 1770100000000 (regenerated with
--     the same values for new ones): MGT-7A for a small company (G4); ADT-1
--     from the AGM event's "auditor appointed" flag (G5); board meetings of a
--     small company / OPC on calendar halves Jul–Dec / Jan–Jun (G6, new
--     frequency calendar_half_yearly); DPT-3 dropped only when the profile says
--     no deposits (G7); PAS-3 in 15 days for a private placement; AOC-4 XBRL /
--     + CFS labels; DIR-3 KYC due 30 June inside the cycle FY (E12); the §9
--     Verify tags (PAS-3, DIR-3 KYC, ADT-1, first ADT-1, LLP Form 11, DPT-3,
--     PAS-6, AOC-4 / MGT-7 thresholds).
--   * Checklists FILING_<RULE_CODE> for the eleven recurring ROC items (§5).
--   * instance_checklist_items: auto_tick 'event' (AOC-4's "AGM held"; the
--     ticking is syncAutoTicks'), ticked_by 'partner' and done_note — a
--     certification line only a partner ticks, with the UDIN as its note.
-- Existing items move the next time their calendar is generated; checklists
-- already created keep their lines (new filings get the per-form ones).
-- ─────────────────────────────────────────────────────────────────────────

-- Up Migration

ALTER TABLE hsdg.compliance_rule_versions
  DROP CONSTRAINT compliance_rule_versions_frequency_check,
  ADD CONSTRAINT compliance_rule_versions_frequency_check
    CHECK (frequency IS NULL OR frequency IN ('monthly','quarterly','half_yearly','calendar_half_yearly','annual','triennial','event','on_demand'));

ALTER TABLE hsdg.instance_checklist_items
  DROP CONSTRAINT instance_checklist_items_auto_tick_check,
  ADD CONSTRAINT instance_checklist_items_auto_tick_check
    CHECK (auto_tick IN ('document','figure','review','lodge','event')),
  ADD COLUMN ticked_by text CHECK (ticked_by IN ('partner')),
  ADD COLUMN done_note text,
  ADD CONSTRAINT instance_checklist_items_partner_note CHECK (
    ticked_by IS NULL OR status <> 'done' OR length(trim(coalesce(done_note, ''))) > 0);
COMMENT ON COLUMN hsdg.instance_checklist_items.ticked_by IS
  'partner: only a partner ticks the line by hand, and the tick carries a note (the UDIN).';
COMMENT ON COLUMN hsdg.instance_checklist_items.done_note IS
  'The note given when the line was ticked (the UDIN on a certification).';

ALTER TABLE hsdg.services NO FORCE ROW LEVEL SECURITY;
ALTER TABLE hsdg.compliance_rules NO FORCE ROW LEVEL SECURITY;
ALTER TABLE hsdg.compliance_rule_versions NO FORCE ROW LEVEL SECURITY;
ALTER TABLE hsdg.government_extensions NO FORCE ROW LEVEL SECURITY;
ALTER TABLE hsdg.compliance_instances NO FORCE ROW LEVEL SECURITY;
ALTER TABLE hsdg.catalogue_templates NO FORCE ROW LEVEL SECURITY;
ALTER TABLE hsdg.catalogue_template_versions NO FORCE ROW LEVEL SECURITY;

UPDATE hsdg.compliance_rule_versions v
   SET condition = x.condition, variants = x.variants, schedule = x.schedule,
       verification = x.verification, late_fee_note = x.late_fee_note, notes = x.notes
  FROM jsonb_to_recordset($json$[
{"code":"ROC_AOC4","condition":null,"variants":[{"when":{"field":"company_subtype","op":"==","value":"opc"},"set":{"calculation_basis":"fy_end","offset_months":0,"offset_days":180,"event_type":null}},{"when":{"field":"has_subsidiaries","op":"==","value":true},"set":{"form_label":"AOC-4 + CFS"}},{"when":{"field":"xbrl_required","op":"==","value":true},"set":{"form_label":"AOC-4 XBRL"}},{"when":{"all":[{"field":"xbrl_required","op":"==","value":true},{"field":"has_subsidiaries","op":"==","value":true}]},"set":{"form_label":"AOC-4 XBRL + CFS"}}],"schedule":null,"verification":"verify","late_fee_note":"Additional fee ₹100/day.","notes":"AOC-4 — 30 days from the AGM (OPC: 180 days from the FY end). Shown on an assumed 30 September AGM until the AGM is recorded."},
{"code":"ROC_MGT7","condition":null,"variants":[{"when":{"field":"company_subtype","op":"==","value":"opc"},"set":{"calculation_basis":"fy_end","offset_months":6,"offset_days":60,"event_type":null,"form_label":"MGT-7A"}},{"when":{"field":"company_subtype","op":"==","value":"small"},"set":{"form_label":"MGT-7A"}}],"schedule":null,"verification":"verify","late_fee_note":"Additional fee ₹100/day.","notes":"MGT-7 / MGT-7A — 60 days from the AGM. Shown on an assumed 30 September AGM until recorded."},
{"code":"ROC_ADT1","condition":{"field":"agm_auditor_appointed","op":"==","value":true},"variants":null,"schedule":null,"verification":"verify","late_fee_note":"Normal-fee form: additional fee is a multiple of the normal fee by days late (2× up to 30 days … 12× after 180).","notes":"ADT-1 — 15 days from the AGM at which the auditor is appointed."},
{"code":"ROC_DPT3","condition":{"field":"deposits","op":"!=","value":false},"variants":null,"schedule":null,"verification":"verify","late_fee_note":"Normal-fee form: additional fee is a multiple of the normal fee by days late (2× up to 30 days … 12× after 180).","notes":"DPT-3 — 30 June. Not created when the profile says there are no deposits or exempted loans."},
{"code":"ROC_PAS6","condition":{"field":"company_subtype","op":"==","value":"unlisted_public"},"variants":null,"schedule":[{"period":"H1","month":11,"day":29,"year_offset":0},{"period":"H2","month":5,"day":30,"year_offset":1}],"verification":"verify","late_fee_note":null,"notes":"PAS-6 — 29 Nov (Apr–Sep); 30 May (Oct–Mar). Unlisted public companies."},
{"code":"ROC_DIR3_KYC","condition":null,"variants":null,"schedule":[{"period":"FY","month":6,"day":30,"year_offset":0}],"verification":"verify","late_fee_note":"Fee ₹5,000 to reactivate a deactivated DIN.","notes":"DIR-3 KYC — 30 June of the FY the three-year cycle falls due in, per DIN (cycle FY 2025-26 → next 30 June 2028)."},
{"code":"LLP_FORM11","condition":null,"variants":null,"schedule":null,"verification":"verify","late_fee_note":"Additional fee ₹100/day.","notes":"LLP Form 11 — within 60 days of the FY end (30 May)."},
{"code":"ROC_BOARD_MEETING","condition":null,"variants":[{"when":{"any":[{"field":"company_subtype","op":"==","value":"small"},{"field":"company_subtype","op":"==","value":"opc"}]},"set":{"frequency":"calendar_half_yearly"}}],"schedule":null,"verification":"verified","late_fee_note":"Penalty u/s 173.","notes":"At least one board meeting each quarter, gap ≤ 120 days. A small company / OPC: one in each half of the calendar year (Jan–Jun, Jul–Dec), at least 90 days apart."},
{"code":"ROC_FIRST_ADT1","condition":null,"variants":null,"schedule":null,"verification":"verify","late_fee_note":null,"notes":"ADT-1 — 15 days from the board’s appointment of the first auditor."},
{"code":"ROC_PAS3","condition":null,"variants":[{"when":{"field":"allotment_private_placement","op":"==","value":true},"set":{"offset_days":15}}],"schedule":null,"verification":"verify","late_fee_note":null,"notes":"PAS-3 — within 30 days of allotment (15 days for a private placement)."}
]$json$::jsonb)
       AS x(code text, condition jsonb, variants jsonb, schedule jsonb, verification text,
            late_fee_note text, notes text),
       hsdg.compliance_rules r
 WHERE r.id = v.compliance_rule_id AND r.code = x.code AND v.version = 1;
