{"code":"FILING_ROC_MGT7","name":"ROC — MGT-7 / MGT-7A (annual return)","body":{"items":[{"code":"AGM_HELD","label":"AGM held","required":true,"autoTick":"event","onlyIf":"hasAgm","sequence":1},{"code":"SHAREHOLDERS","label":"Shareholder / debenture-holder list and transfers in the year","slotCode":"SH_LIST","required":true,"autoTick":"document","sequence":2},{"code":"MEETINGS","label":"Board and committee meetings and attendance for the year","autoTick":"meetings","sequence":3},{"code":"MGT8","label":"MGT-8 by a CS in practice","slotCode":"MGT8","required":true,"autoTick":"document","onlyIf":"mgt8Required","note":"Client dependency: a CS in practice certifies it.","sequence":4},{"code":"FORM","label":"Form prepared, pre-scrutiny passed","slotCode":"ROC_FORM","required":true,"autoTick":"document","sequence":5},{"code":"DSC","label":"Signed with DSC (director / designated partner)","required":true,"sequence":6},{"code":"REVIEW","label":"Review","required":true,"autoTick":"review","sequence":7},{"code":"LODGE","label":"Lodge (SRN)","slotCode":"ACK_ROC","required":true,"autoTick":"lodge","sequence":8}]}},
{"code":"FILING_ROC_ADT1","name":"ROC — ADT-1 (auditor appointment)","body":{"items":[{"code":"RESOLUTION","label":"Resolution appointing the auditor (term and remuneration)","slotCode":"RESOLUTION","required":true,"autoTick":"document","sequence":1},{"code":"CONSENT","label":"Auditor’s consent and eligibility certificate (s.139(1), s.141)","slotCode":"AUDITOR_CONSENT","required":true,"autoTick":"document","sequence":2},{"code":"INTIMATION","label":"Appointment letter to the auditor","sequence":3},{"code":"FORM","label":"Form prepared","slotCode":"ROC_FORM","required":true,"autoTick":"document","sequence":4},{"code":"DSC","label":"Signed with DSC (director / designated partner)","required":true,"sequence":5},{"code":"REVIEW","label":"Review","required":true,"autoTick":"review","sequence":6},{"code":"LODGE","label":"Lodge (SRN)","slotCode":"ACK_ROC","required":true,"autoTick":"lodge","sequence":7}]}},
{"code":"FILING_ROC_DPT3","name":"ROC — DPT-3 (deposits and exempted loans)","body":{"items":[{"code":"SCHEDULE","label":"Loans / receipts outstanding at 31 March (lender-wise schedule)","slotCode":"DPT_DATA","required":true,"autoTick":"document","sequence":1},{"code":"AUDITOR_CERT","label":"Auditor’s certificate (where deposits are held)","slotCode":"DPT_AUDITOR_CERT","required":false,"autoTick":"document","sequence":2},{"code":"FORM","label":"Form prepared","slotCode":"ROC_FORM","required":true,"autoTick":"document","sequence":3},{"code":"DSC","label":"Signed with DSC (director / designated partner)","required":true,"sequence":4},{"code":"REVIEW","label":"Review","required":true,"autoTick":"review","sequence":5},{"code":"LODGE","label":"Lodge (SRN)","slotCode":"ACK_ROC","required":true,"autoTick":"lodge","sequence":6}]}},
{"code":"FILING_ROC_MSME1","name":"ROC — MSME-1 (dues to micro / small suppliers)","body":{"items":[{"code":"MSME_LIST","label":"Supplier-wise dues over 45 days, with amounts, dates and reasons","slotCode":"MSME_DATA","required":true,"autoTick":"document","sequence":1},{"code":"FORM","label":"Form prepared","slotCode":"ROC_FORM","required":true,"autoTick":"document","sequence":2},{"code":"DSC","label":"Signed with DSC (director / designated partner)","required":true,"sequence":3},{"code":"REVIEW","label":"Review","required":true,"autoTick":"review","sequence":4},{"code":"LODGE","label":"Lodge (SRN)","slotCode":"ACK_ROC","required":true,"autoTick":"lodge","sequence":5}]}},
{"code":"FILING_ROC_PAS6","name":"ROC — PAS-6 (share capital reconciliation)","body":{"items":[{"code":"RTA_DATA","label":"Depository / RTA holding data for the half-year","slotCode":"PAS6_DATA","required":true,"autoTick":"document","sequence":1},{"code":"CERT_REPORT","label":"Reconciliation report signed by a practising CA / CS","slotCode":"PAS6_CERT","required":true,"autoTick":"document","sequence":2},{"code":"FORM","label":"Form prepared","slotCode":"ROC_FORM","required":true,"autoTick":"document","sequence":3},{"code":"DSC","label":"Signed with DSC (director / designated partner)","required":true,"sequence":4},{"code":"REVIEW","label":"Review","required":true,"autoTick":"review","sequence":5},{"code":"LODGE","label":"Lodge (SRN)","slotCode":"ACK_ROC","required":true,"autoTick":"lodge","sequence":6}]}},
{"code":"FILING_ROC_DIR3_KYC","name":"ROC — DIR-3 KYC","body":{"items":[{"code":"KYC_DOCS","label":"PAN, Aadhaar, address proof; mobile and e-mail OTP verified","slotCode":"KYC_DOCS","required":true,"autoTick":"document","sequence":1},{"code":"CERT","label":"Certified by a practising professional (e-form only)","sequence":2},{"code":"DSC","label":"Signed with the director’s own DSC","required":true,"sequence":3},{"code":"REVIEW","label":"Review","required":true,"autoTick":"review","sequence":4},{"code":"LODGE","label":"Lodge (SRN)","slotCode":"ACK_ROC","required":true,"autoTick":"lodge","sequence":5}]}},
{"code":"FILING_LLP_FORM11","name":"LLP — Form 11 (annual return)","body":{"items":[{"code":"PARTNERS","label":"Partners, contributions and changes in the year","slotCode":"LLP_PARTNERS","required":true,"autoTick":"document","sequence":1},{"code":"FORM","label":"Form prepared","slotCode":"ROC_FORM","required":true,"autoTick":"document","sequence":2},{"code":"DSC","label":"Signed with DSC (designated partners)","required":true,"sequence":3},{"code":"REVIEW","label":"Review","required":true,"autoTick":"review","sequence":4},{"code":"LODGE","label":"Lodge (SRN)","slotCode":"ACK_ROC","required":true,"autoTick":"lodge","sequence":5}]}},
{"code":"FILING_LLP_FORM8","name":"LLP — Form 8 (statement of account and solvency)","body":{"items":[{"code":"ACCOUNTS","label":"Signed statement of account; audit report where the LLP is audited","slotCode":"LLP_ACCOUNTS","required":true,"autoTick":"document","sequence":1},{"code":"SOLVENCY","label":"Solvency declaration by the designated partners","required":true,"sequence":2},{"code":"CERT","label":"Certified by a practising CA / CS / CMA","required":true,"tickedBy":"partner","note":"Partner ticks; UDIN in the note.","sequence":3},{"code":"FORM","label":"Form prepared","slotCode":"ROC_FORM","required":true,"autoTick":"document","sequence":4},{"code":"DSC","label":"Signed with DSC (designated partners)","required":true,"sequence":5},{"code":"REVIEW","label":"Review","required":true,"autoTick":"review","sequence":6},{"code":"LODGE","label":"Lodge (SRN)","slotCode":"ACK_ROC","required":true,"autoTick":"lodge","sequence":7}]}}
]$json$::jsonb) AS t(code text, name text, body jsonb)
JOIN hsdg.catalogue_templates ct ON ct.code = t.code
ON CONFLICT DO NOTHING;

