DELETE FROM hsdg.catalogue_template_versions v USING hsdg.catalogue_templates t
 WHERE v.catalogue_template_id = t.id AND t.code = ANY(ARRAY['FILING_ROC_AGM','FILING_ROC_BOARD_MEETING','FILING_ROC_AOC4','FILING_ROC_MGT7','FILING_ROC_ADT1','FILING_ROC_DPT3','FILING_ROC_MSME1','FILING_ROC_PAS6','FILING_ROC_DIR3_KYC','FILING_LLP_FORM11','FILING_LLP_FORM8']);
DELETE FROM hsdg.catalogue_templates WHERE code = ANY(ARRAY['FILING_ROC_AGM','FILING_ROC_BOARD_MEETING','FILING_ROC_AOC4','FILING_ROC_MGT7','FILING_ROC_ADT1','FILING_ROC_DPT3','FILING_ROC_MSME1','FILING_ROC_PAS6','FILING_ROC_DIR3_KYC','FILING_LLP_FORM11','FILING_LLP_FORM8']);

UPDATE hsdg.compliance_rule_versions v
   SET condition = x.condition, variants = x.variants, schedule = x.schedule,
       verification = x.verification, late_fee_note = x.late_fee_note, notes = x.notes
  FROM jsonb_to_recordset($json$[
{"code":"ROC_AOC4","condition":null,"variants":[{"when":{"field":"company_subtype","op":"==","value":"opc"},"set":{"calculation_basis":"fy_end","offset_months":0,"offset_days":180,"event_type":null}}],"schedule":null,"verification":"verified","late_fee_note":"Additional fee ₹100/day.","notes":"AOC-4 — 30 days from the AGM (OPC: 180 days from the FY end). Shown on an assumed 30 September AGM until the AGM is recorded."},
{"code":"ROC_MGT7","condition":null,"variants":[{"when":{"field":"company_subtype","op":"==","value":"opc"},"set":{"calculation_basis":"fy_end","offset_months":6,"offset_days":60,"event_type":null,"form_label":"MGT-7A"}}],"schedule":null,"verification":"verified","late_fee_note":"Additional fee ₹100/day.","notes":"MGT-7 / MGT-7A — 60 days from the AGM. Shown on an assumed 30 September AGM until recorded."},
{"code":"ROC_ADT1","condition":{"field":"auditor_appointed_at_agm","op":"==","value":true},"variants":null,"schedule":null,"verification":"verified","late_fee_note":"Additional fee ₹100/day.","notes":"ADT-1 — 15 days from the AGM at which the auditor is appointed."},
{"code":"ROC_DPT3","condition":null,"variants":null,"schedule":null,"verification":"verified","late_fee_note":"Additional fee ₹100/day.","notes":"DPT-3 — 30 June."},
{"code":"ROC_PAS6","condition":{"field":"company_subtype","op":"==","value":"unlisted_public"},"variants":null,"schedule":[{"period":"H1","month":11,"day":29,"year_offset":0},{"period":"H2","month":5,"day":30,"year_offset":1}],"verification":"verified","late_fee_note":null,"notes":"PAS-6 — 29 Nov (Apr–Sep); 30 May (Oct–Mar). Unlisted public companies."},
{"code":"ROC_DIR3_KYC","condition":null,"variants":null,"schedule":[{"period":"FY","month":6,"day":30,"year_offset":1}],"verification":"verified","late_fee_note":"Fee ₹5,000 to reactivate a deactivated DIN.","notes":"DIR-3 KYC — 30 June, once every three financial years, per DIN."},
{"code":"LLP_FORM11","condition":null,"variants":null,"schedule":null,"verification":"verified","late_fee_note":"Additional fee ₹100/day.","notes":"LLP Form 11 — within 60 days of the FY end (30 May)."},
{"code":"ROC_BOARD_MEETING","condition":null,"variants":[{"when":{"any":[{"field":"company_subtype","op":"==","value":"small"},{"field":"company_subtype","op":"==","value":"opc"}]},"set":{"period_filter":["Q2","Q4"]}}],"schedule":null,"verification":"verified","late_fee_note":"Penalty u/s 173.","notes":"At least one board meeting each quarter, gap ≤ 120 days (one per half-year for small companies / OPC)."},
{"code":"ROC_FIRST_ADT1","condition":null,"variants":null,"schedule":null,"verification":"verified","late_fee_note":null,"notes":"ADT-1 — 15 days from the board’s appointment of the first auditor."},
{"code":"ROC_PAS3","condition":null,"variants":null,"schedule":null,"verification":"verified","late_fee_note":null,"notes":"PAS-3 — within 30 days of allotment (15 days for a private placement)."}
]$json$::jsonb)
       AS x(code text, condition jsonb, variants jsonb, schedule jsonb, verification text,
            late_fee_note text, notes text),
       hsdg.compliance_rules r
 WHERE r.id = v.compliance_rule_id AND r.code = x.code AND v.version = 1;
UPDATE hsdg.compliance_rules r SET description = x.notes
  FROM jsonb_to_recordset($json$[
{"code":"ROC_AOC4","condition":null,"variants":[{"when":{"field":"company_subtype","op":"==","value":"opc"},"set":{"calculation_basis":"fy_end","offset_months":0,"offset_days":180,"event_type":null}}],"schedule":null,"verification":"verified","late_fee_note":"Additional fee ₹100/day.","notes":"AOC-4 — 30 days from the AGM (OPC: 180 days from the FY end). Shown on an assumed 30 September AGM until the AGM is recorded."},
{"code":"ROC_MGT7","condition":null,"variants":[{"when":{"field":"company_subtype","op":"==","value":"opc"},"set":{"calculation_basis":"fy_end","offset_months":6,"offset_days":60,"event_type":null,"form_label":"MGT-7A"}}],"schedule":null,"verification":"verified","late_fee_note":"Additional fee ₹100/day.","notes":"MGT-7 / MGT-7A — 60 days from the AGM. Shown on an assumed 30 September AGM until recorded."},
{"code":"ROC_ADT1","condition":{"field":"auditor_appointed_at_agm","op":"==","value":true},"variants":null,"schedule":null,"verification":"verified","late_fee_note":"Additional fee ₹100/day.","notes":"ADT-1 — 15 days from the AGM at which the auditor is appointed."},
{"code":"ROC_DPT3","condition":null,"variants":null,"schedule":null,"verification":"verified","late_fee_note":"Additional fee ₹100/day.","notes":"DPT-3 — 30 June."},
{"code":"ROC_PAS6","condition":{"field":"company_subtype","op":"==","value":"unlisted_public"},"variants":null,"schedule":[{"period":"H1","month":11,"day":29,"year_offset":0},{"period":"H2","month":5,"day":30,"year_offset":1}],"verification":"verified","late_fee_note":null,"notes":"PAS-6 — 29 Nov (Apr–Sep); 30 May (Oct–Mar). Unlisted public companies."},
{"code":"ROC_DIR3_KYC","condition":null,"variants":null,"schedule":[{"period":"FY","month":6,"day":30,"year_offset":1}],"verification":"verified","late_fee_note":"Fee ₹5,000 to reactivate a deactivated DIN.","notes":"DIR-3 KYC — 30 June, once every three financial years, per DIN."},
{"code":"LLP_FORM11","condition":null,"variants":null,"schedule":null,"verification":"verified","late_fee_note":"Additional fee ₹100/day.","notes":"LLP Form 11 — within 60 days of the FY end (30 May)."},
{"code":"ROC_BOARD_MEETING","condition":null,"variants":[{"when":{"any":[{"field":"company_subtype","op":"==","value":"small"},{"field":"company_subtype","op":"==","value":"opc"}]},"set":{"period_filter":["Q2","Q4"]}}],"schedule":null,"verification":"verified","late_fee_note":"Penalty u/s 173.","notes":"At least one board meeting each quarter, gap ≤ 120 days (one per half-year for small companies / OPC)."},
{"code":"ROC_FIRST_ADT1","condition":null,"variants":null,"schedule":null,"verification":"verified","late_fee_note":null,"notes":"ADT-1 — 15 days from the board’s appointment of the first auditor."},
{"code":"ROC_PAS3","condition":null,"variants":null,"schedule":null,"verification":"verified","late_fee_note":null,"notes":"PAS-3 — within 30 days of allotment (15 days for a private placement)."}
]$json$::jsonb) AS x(code text, notes text)
 WHERE r.code = x.code;

